                                    try:
                                        self._pinned_buffers[key] = torch.empty(
                                            tensor.shape,
                                            dtype=tensor.dtype,
                                            pin_memory=True,
                                        )
                                    except:
                                        # Fallback to regular transfer if pinned memory allocation fails
                                        moved_tensors.append(
                                            tensor.to(device, non_blocking=True)
                                        )
                                        continue

