                                pinned.copy_(tensor)
                                moved_tensors.append(
                                    pinned.to(device, non_blocking=True)
                                )
                        else:
                            # For GPU->CPU or GPU->GPU transfers
                            for tensor in tensors_to_move:
                                moved_tensors.append(
